let editorContent; // Stores the current code in the editor
let originalCode; // Stores the original sketch code for reference
let codeEditor; // DOM element for the code editor (textarea)
let previewContainer; // DIV to hold the user's p5 canvas
let userSketchInstance = null; // Holds the p5 instance for the user's sketch
let errorDisplay; // Area to display errors
let defaultSketch; // Default sketch code to start with
let activeTab = 'editor'; // Current active tab ('editor', 'settings', 'info')

// --- UI Elements ---
