let settingsPanel;
let themeToggle;
let fontSizeLabel;
let fontSizeDecrease;
let fontSizeIncrease;
let autoIndentToggle;
let lineNumbersToggle; // Note: Visual line numbers require a dedicated editor library
let resetButton;
