// --- FPS Counter Smoothing ---
let displayFps = 60; // The smoothed FPS value to display
let fpsFrameCount = 0; // Frames counted during the current interval
let lastFpsUpdateTime = 0; // Time (in ms) when FPS was last calculated/updated
const fpsUpdateInterval = 500; // Calculate average FPS every 500ms (half a second)

// --- Background Effects ---
let bgParticles = [];
const NUM_BG_PARTICLES = 30; // Subtle number

// Color themes (Refined Catppuccin Macchiato Inspired)
