// Default sketch - NOW EXPLICITLY USING INSTANCE MODE ASSIGNMENT
defaultSketch = `
// Welcome! This editor runs p5.js in INSTANCE MODE.
// Your code MUST define functions on the 'p' object.
// Use 'p.' before all p5 functions/variables (p.fill, p.width, p.mouseX etc.)

class Particle {
  constructor(x, y) {
    this.position = p.createVector(x, y);
    this.velocity = p.createVector(p.random(-1, 1), p.random(-1, 1));
    this.size = p.random(CONFIG.MIN_SIZE, CONFIG.MAX_SIZE);
    this.hue = p.random(360);
    this.saturation = p.random(60, 100);
    this.brightness = p.random(80, 100);
  }

  update() {
    this.position.add(this.velocity);

    // Wrap around edges
    if (this.position.x < 0) this.position.x = p.width;
    if (this.position.x > p.width) this.position.x = 0;
    if (this.position.y < 0) this.position.y = p.height;
    if (this.position.y > p.height) this.position.y = 0;

    // Slowly cycle hue
    this.hue = (this.hue + CONFIG.HUE_SPEED) % 360;
  }

  show() {
    p.fill(this.hue, this.saturation, this.brightness, 1);
    p.ellipse(this.position.x, this.position.y, this.size);
  }
}

let particles = [];

const CONFIG = {
  NUM_PARTICLES: 80,       // Total number of particles
  MIN_SIZE: 4,             // Smallest particle diameter
  MAX_SIZE: 12,            // Largest particle diameter
  LINK_DISTANCE: 120,      // Max distance to draw a line
  TRAIL_ALPHA: 0.15,       // Background fade for trails
  HUE_SPEED: 0.2,          // How fast each particle cycles hue
  REPULSE_RADIUS: 60,      // Mouse repulsion distance
  REPULSE_FORCE: 1.2       // Strength of repulsion
};

p.setup = function() {
  p.createCanvas(p.windowWidth, p.windowHeight);
  p.colorMode(p.HSB, 360, 100, 100, 1);
  p.noStroke();

  // Initialize particles
  for (let i = 0; i < CONFIG.NUM_PARTICLES; i++) {
    particles.push(new Particle(p.random(p.width), p.random(p.height)));
  }
};

p.draw = function() {
  // Fade background slightly to create motion trails
  p.background(230, 50, 15, CONFIG.TRAIL_ALPHA);

  // Enable glow effect for connecting lines
  p.drawingContext.shadowBlur = 16;
  p.drawingContext.shadowColor = 'rgba(255,255,255,0.1)';
  p.blendMode(p.ADD);

  // Draw connections
  for (let i = 0; i < particles.length; i++) {
    const a = particles[i];
    a.update();

    for (let j = i + 1; j < particles.length; j++) {
      const b = particles[j];
      const d = p.dist(a.position.x, a.position.y, b.position.x, b.position.y);

      if (d < CONFIG.LINK_DISTANCE) {
        const alpha = p.map(d, 0, CONFIG.LINK_DISTANCE, 0.8, 0);
        p.strokeWeight(1);
        p.stroke(a.hue, a.saturation, a.brightness, alpha);
        p.line(a.position.x, a.position.y, b.position.x, b.position.y);
      }
    }
  }

  // Reset to normal drawing for particles
  p.blendMode(p.BLEND);
  p.drawingContext.shadowBlur = 0;
  p.noStroke();

  // Draw particles on top
  particles.forEach(pt => pt.show());
};

p.mouseMoved = function() {
  const m = p.createVector(p.mouseX, p.mouseY);
  particles.forEach(pt => {
    var d = p5.Vector.dist(m, pt.position);
    if (d < CONFIG.REPULSE_RADIUS) {
      const force = p5.Vector.sub(pt.position, m)
        .setMag(CONFIG.REPULSE_FORCE);
      pt.velocity.add(force);
      pt.velocity.limit(4);
    }
  });
};

p.windowResized = function() {
  p.resizeCanvas(p.windowWidth, p.windowHeight);
};
`;

// ==================================================
// Editor Setup (Runs in the main global p5 scope)
// ==================================================

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);
  // p5.js defaults to frameRate(60) - we keep this for the editor UI
  // User sketches can set their own frame rate using p.frameRate() in their setup
  console.log(`Editor UI frame rate target: ${getTargetFrameRate()} (default is 60)`);

  setupUI(); // Create DOM elements first
  injectGlobalStyles(); // Inject base styles and font
  originalCode = defaultSketch;
  updateCodeEditor(defaultSketch);
  overrideConsole(); // Setup console interception
  setupBackgroundParticles(); // Initialize background particles
  applyTheme(); // Apply initial theme styles to DOM elements

  lastFpsUpdateTime = millis(); // Initialize FPS update timer

  // Initial sketch load with a slight delay after UI setup
  setTimeout(() => updateSketch(defaultSketch), 150);
}

function setupBackgroundParticles() {
    // No p5 color calls here, just setup data structure
    bgParticles = []; // Clear existing
    for (let i = 0; i < NUM_BG_PARTICLES; i++) {
        bgParticles.push({
            // Use width/height from the main editor canvas for initial position
            pos: createVector(random(width), random(height)),
            vel: createVector(random(-0.3, 0.3), random(-0.3, 0.3)),
            size: random(1, 3),
        });
    }
}

function injectGlobalStyles() {
    let styleElement = document.getElementById('editor-styles');
    if (!styleElement) {
        styleElement = document.createElement('style');
        styleElement.id = 'editor-styles';
        document.head.appendChild(styleElement);
    }

    const currentTheme = themes[darkMode ? 'dark' : 'light'];

    // Font face (ensure path is correct relative to index.html)
    const fontFaceRule = `
      @font-face {
        font-family: '${FONT_NAME}';
        src: url('POIAeronautTrial-Regular.otf') format('opentype');
        font-weight: ${FONT_WEIGHT_REGULAR};
        font-style: normal;
      }
      /* Add bold if available:
      @font-face {
        font-family: '${FONT_NAME}';
        src: url('POIAeronautTrial-Bold.otf') format('opentype');
        font-weight: ${FONT_WEIGHT_BOLD};
        font-style: normal;
      } */
    `;

    // Global styles and base element styling
    const globalRules = `
      body {
        font-family: '${FONT_NAME}', sans-serif;
        overflow: hidden;
        margin: 0;
        background-color: ${currentTheme.background}; /* Set body bg */
        color: ${currentTheme.foreground};
        /* Improve text rendering */
        -webkit-font-smoothing: antialiased;
        -moz-osx-font-smoothing: grayscale;
      }
      /* Apply font globally, allow overrides */
      button, input, select, textarea, div, span, p, label {
         font-family: inherit;
         font-size: inherit; /* Let specific elements override */
         color: inherit;
         box-sizing: border-box; /* Better layout control */
      }
      /* Code areas use monospace fallback */
       #code-editor, #error-display, #console-area {
          font-family: '${FONT_NAME}', monospace;
          line-height: 1.5;
          font-size: ${fontSize}px; /* Base font size, editor overrides later */
      }
       #error-display code, #info-display code { /* Inline code styling */
           background-color: ${currentTheme.panel_light};
           padding: 2px 5px;
           border-radius: 4px;
           font-size: 0.9em;
       }
       #error-display pre, #info-display pre { /* Code block styling */
           background-color: ${currentTheme.panel};
           border: 1px solid ${currentTheme.border};
           padding: 12px;
           border-radius: 4px;
           font-size: ${fontSize * 0.9}px; /* Slightly smaller */
           overflow-x: auto;
           white-space: pre-wrap; /* Wrap long lines */
           word-break: break-all; /* Break long words if needed */
       }


      /* Basic button styling */
      button {
          border: none;
          padding: 8px 16px;
          border-radius: 6px;
          cursor: pointer;
          font-weight: ${FONT_WEIGHT_BOLD};
          transition: all 0.15s ease-in-out;
          box-shadow: 0 1px 3px ${currentTheme.shadow};
          background-color: ${currentTheme.accent}; /* Base button color */
          color: ${currentTheme.editor}; /* Base button text color */
      }
      button:hover {
          transform: translateY(-1px);
          box-shadow: 0 3px 6px ${currentTheme.shadow};
          background-color: ${currentTheme.accent_hover}; /* Hover color */
      }
      button:active {
          transform: translateY(0px);
          box-shadow: 0 1px 3px ${currentTheme.shadow};
          filter: brightness(0.95);
      }

      /* Checkbox styling */
      input[type="checkbox"] {
          margin-right: 8px;
          vertical-align: middle;
          width: 16px;
          height: 16px;
          cursor: pointer;
          accent-color: ${currentTheme.accent}; /* Modern browsers */
          background-color: ${currentTheme.editor}; /* Background */
          border: 1px solid ${currentTheme.border};
          border-radius: 3px;
          appearance: none; /* Remove default appearance */
          position: relative; /* For custom checkmark */
          transition: background-color 0.15s ease;
      }
       input[type="checkbox"]:checked {
           background-color: ${currentTheme.accent};
           border-color: ${currentTheme.accent};
       }
       /* Custom checkmark using ::after pseudo-element */
       input[type="checkbox"]:checked::after {
           content: '✔'; /* Checkmark character */
           position: absolute;
           top: -2px; /* Adjust position */
           left: 2px; /* Adjust position */
           font-size: 12px;
           color: ${currentTheme.editor}; /* Color of the checkmark */
           font-weight: bold;
       }

      input[type="checkbox"] + span { /* Style label next to checkbox */
           vertical-align: middle;
           cursor: pointer;
           user-select: none; /* Prevent text selection on click */
      }

       /* Panel styling */
      .panel {
          background-color: ${currentTheme.panel};
          border: 1px solid ${currentTheme.border};
