      textarea, div { /* Apply to potential scrollable elements */
         scrollbar-width: thin;
         scrollbar-color: ${currentTheme.panel_light} ${currentTheme.editor};
       }
    `;

    styleElement.innerHTML = fontFaceRule + globalRules;
}


function draw() {
  // --- Calculate Smoothed FPS ---
  fpsFrameCount++;
  let currentTime = millis();
  let elapsed = currentTime - lastFpsUpdateTime;

  if (elapsed >= fpsUpdateInterval) {
    // Calculate FPS over the interval
    // (frames counted * 1000 ms/s) / elapsed time in ms
    displayFps = Math.round((fpsFrameCount * 1000.0) / elapsed);
    // Reset for next interval
    fpsFrameCount = 0;
    lastFpsUpdateTime = currentTime;
  }

  // --- Drawing ---
  var currentTheme = themes[darkMode ? 'dark' : 'light'];
  // Draw background particles *first*
  drawBgParticles();

  // Draw UI elements over the particles
  drawTopBar();
  drawEditorPanel(); // Includes resize handle
  drawPreviewArea(); // Mostly just a background area unless info/settings visible
  drawStatusBar(); // Now uses smoothed displayFps

  // Handle dragging state
  if (isDragging) {
    let newWidthPercent = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width) * 100;
    editorWidthPercent = constrain(newWidthPercent, 15, 85);
    repositionElements(); // Reposition dynamically
  }

  // Update cursor for resize handle
  let handleX = width * (editorWidthPercent / 100);
  const resizerWidth = 10;
  const topBarHeight = 45;
  const statusBarHeight = 25;
  if (!isDragging && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > handleX - resizerWidth && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < handleX + resizerWidth && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > topBarHeight && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height - statusBarHeight) {
     cursor('ew-resize');
  } else if (!isDragging) {
     cursor(ARROW);
  }
}

function drawBgParticles() {
    var currentTheme = themes[darkMode ? 'dark' : 'light'];
    // Use p5 color object now that setup is complete
    let particleColor = color(currentTheme.foreground);
    particleColor.setAlpha(40); // Even more subtle alpha

    background(currentTheme.background); // Clear background each frame

    noStroke();
    fill(particleColor);

    for (let p of bgParticles) {
        p.pos.add(p.vel);

        // Wrap edges using main canvas width/height
        if (p.pos.x < -p.size) p.pos.x = width + p.size;
        if (p.pos.x > width + p.size) p.pos.x = -p.size;
        if (p.pos.y < -p.size) p.pos.y = height + p.size;
        if (p.pos.y > height + p.size) p.pos.y = -p.size;

        ellipse(p.pos.x, p.pos.y, p.size, p.size);
    }
}

function setupUI() {
