  fontSizeDecrease.style('padding', '4px 10px'); // Make buttons smaller
  fontSizeDecrease.style('margin-right', '5px');
  fontSizeDecrease.style('min-width', '30px'); // Ensure minimum width

  fontSizeIncrease = createSettingButton('+', () => {
    fontSize = min(24, fontSize + 1);
    fontSizeLabel.html(`Font Size: ${fontSize}`);
    applyTheme();
  });
  fontSizeIncrease.style('padding', '4px 10px');
  fontSizeIncrease.style('min-width', '30px');

  createSectionTitle('Editor Options');

  // Auto Indent Checkbox
const indentCheck = createSettingCheckbox(
