      } else {
          // If already on editor tab, update directly
          updateSketch(defaultSketch);
      }
    }
  });
}


// ==================================================
// Element Positioning & Resizing
// ==================================================

function repositionElements() {
  var topBarHeight = 45;
  var statusBarHeight = 25;
  const editorPadding = 15;
  const buttonHeight = 35;
  const errorMinHeight = 50;
  const consoleMinHeight = 60;
  var resizerWidth = 10; // Width of the draggable resizer area

  let availableHeight = height - topBarHeight - statusBarHeight;
  let editorPaneWidth = width * (editorWidthPercent / 100);
  let previewPaneWidth = width * (1 - editorWidthPercent / 100);

  // --- Visibility based on active tab ---
  let editorVisible = activeTab === 'editor';
  let settingsVisible = activeTab === 'settings';
  let infoVisible = activeTab === 'info';

  codeEditor.style('display', editorVisible ? 'block' : 'none');
  updateButton.style('display', editorVisible ? 'block' : 'none');
  previewContainer.style('display', editorVisible ? 'block' : 'none');

  if (settingsPanel) {
      settingsPanel.style('display', settingsVisible ? 'block' : 'none');
  }

  // Error/console layout depends on tab
  errorDisplay.style('display', 'block'); // Assume visible unless explicitly hidden
  consoleArea.style('display', 'block');

  let currentEditorY = topBarHeight + editorPadding;
  // Adjust width to account for resizer handle area visually centered
  let editorPaneInnerWidth = max(0, editorPaneWidth - editorPadding - (resizerWidth / 2));

  if (editorVisible) {
      let remainingHeight = max(0, availableHeight - (4 * editorPadding) - buttonHeight);
      let consoleHeight = max(consoleMinHeight, remainingHeight * 0.25);
      let errorHeight = max(errorMinHeight, remainingHeight * 0.15);
      let editorHeight = max(0, remainingHeight - consoleHeight - errorHeight);

      codeEditor.position(editorPadding, currentEditorY);
      codeEditor.size(editorPaneInnerWidth, editorHeight);
      currentEditorY += editorHeight + editorPadding;

      updateButton.position(editorPadding, currentEditorY);
      updateButton.size(editorPaneInnerWidth, buttonHeight);
      currentEditorY += buttonHeight + editorPadding;

      errorDisplay.position(editorPadding, currentEditorY);
      errorDisplay.size(editorPaneInnerWidth, errorHeight);
      currentEditorY += errorHeight + editorPadding;

      consoleArea.position(editorPadding, currentEditorY);
      consoleArea.size(editorPaneInnerWidth, consoleHeight);

  } else if (infoVisible) {
      var remainingHeight = max(0, availableHeight - (3 * editorPadding)); // Only 2 gaps needed
      var consoleHeight = max(consoleMinHeight, remainingHeight * 0.3);
      let infoHeight = max(0, remainingHeight - consoleHeight);

      errorDisplay.position(editorPadding, currentEditorY); // Info shown in errorDisplay
      errorDisplay.size(editorPaneInnerWidth, infoHeight);
      currentEditorY += infoHeight + editorPadding;

      consoleArea.position(editorPadding, currentEditorY);
      consoleArea.size(editorPaneInnerWidth, consoleHeight);

  } else if (settingsVisible) {
      // Settings panel takes the right pane, hide error/console in left
       errorDisplay.style('display', 'none');
       consoleArea.style('display', 'none');
  } else {
       // Fallback: Hide everything in the left pane except maybe title/status?
       errorDisplay.style('display', 'none');
       consoleArea.style('display', 'none');
  }


  // --- Right Pane Elements ---
  // Calculate start X after the center of the resizer handle
  let rightPaneX = editorPaneWidth + (resizerWidth / 2);
  let rightPaneInnerWidth = max(0, width - rightPaneX - editorPadding); // Account for right padding
  let rightPaneInnerHeight = max(0, availableHeight - (2 * editorPadding)); // Top/bottom padding

  // Preview container (only on Editor tab)
  previewContainer.position(rightPaneX, topBarHeight + editorPadding);
  previewContainer.size(rightPaneInnerWidth, rightPaneInnerHeight);

  // Settings Panel (only on Settings tab)
  if (settingsPanel) {
      settingsPanel.position(rightPaneX, topBarHeight + editorPadding);
      settingsPanel.size(rightPaneInnerWidth, rightPaneInnerHeight);
  }

  // Trigger sketch resize if it exists and editor tab is active
  if (userSketchInstance && editorVisible && typeof userSketchInstance.windowResized === 'function') {
      const previewRect = previewContainer.elt.getBoundingClientRect();
      if (previewRect.width > 0 && previewRect.height > 0) {
          // Check if dimensions actually changed to avoid redundant calls
          if (userSketchInstance.width !== previewRect.width || userSketchInstance.height !== previewRect.height) {
              userSketchInstance.width = previewRect.width;
              userSketchInstance.height = previewRect.height;
              userSketchInstance.windowWidth = previewRect.width;
              userSketchInstance.windowHeight = previewRect.height;
              // Use timeout to allow DOM to settle before calling user's resize function
              setTimeout(() => {
                  if (userSketchInstance && typeof userSketchInstance.windowResized === 'function') {
                      try {
                           userSketchInstance.windowResized();
                      } catch (resizeError) {
                           console.error("Error in user's windowResized function:", resizeError);
                           // Optionally display this error in the error panel too
                            errorDisplay.html(`<strong style="color:${themes[darkMode ? 'dark' : 'light'].secondary};">Runtime Error (in windowResized):</strong><br>${resizeError.message}`);
                            errorDisplay.style('color', themes[darkMode ? 'dark' : 'light'].secondary);
                            errorDisplay.style('border', `1px solid ${themes[darkMode ? 'dark' : 'light'].secondary}`);
                      }
                  }
              }, 0);
          }
      }
  }
}


function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  setupBackgroundParticles(); // Re-distribute particles
  repositionElements();
  applyTheme(); // Re-apply theme to potentially update CSS rules etc.
}


