  // textStyle(BOLD); // Assumes font supports weight or use bold version
  text('P5.js Live Editor', 20, topBarHeight / 2 + 2); // Adjust vertical align slightly

  // Draw Tabs
  const tabs = [
    { name: 'Editor', id: 'editor' },
    { name: 'Settings', id: 'settings' },
    { name: 'Info', id: 'info' }
  ];

  const tabWidth = 100;
  const tabSpacing = 5;
  let startX = width - (tabs.length * (tabWidth + tabSpacing)) - 15; // Position from right edge

  for (let i = 0; i < tabs.length; i++) {
    let tab = tabs[i];
    let currentTabX = startX + i * (tabWidth + tabSpacing);
    let isActive = activeTab === tab.id;
    let isHover = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > currentTabX && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < currentTabX + tabWidth && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < topBarHeight;

    // Tab Background Color
    if (isActive) {
        fill(currentTheme.accent);
    } else if (isHover) {
        fill(currentTheme.panel_light);
    } else {
        fill(currentTheme.panel); // Match top bar bg
    }

    // Draw Tab Shape (rounded top)
    noStroke();
    rect(currentTabX, 0, tabWidth, topBarHeight, 8, 8, 0, 0);

    // Add subtle borders for non-active tabs for definition
    if (!isActive) {
        stroke(currentTheme.border);
        strokeWeight(0.5); // Very thin border
        line(currentTabX + 1, 0, currentTabX + tabWidth - 1, 0); // Top line
        line(currentTabX, 1, currentTabX, topBarHeight - 1); // Left line
        line(currentTabX + tabWidth -1, 1, currentTabX + tabWidth -1, topBarHeight -1); // Right line
    }

    // Tab Text Color
    fill(isActive ? currentTheme.editor : (isHover ? currentTheme.accent : currentTheme.foreground_subtle)); // Subtle non-active text
    noStroke();
    textAlign(CENTER, CENTER);
    textFont(FONT_NAME);
    // textStyle(isActive ? BOLD : NORMAL); // Bold active tab text
    textSize(14);
    text(tab.name, currentTabX + tabWidth / 2, topBarHeight / 2 + 1); // Adjust vertical align

    // Click Detection - use mouseReleased to prevent drag-selecting tabs
    // Store hover state for use in mouseReleased
    tab.isHovering = isHover; // Add temporary state to tab object
  }
  noStroke(); // Reset stroke
}


function handleTabChange(newTabId, callback = null) { // Added optional callback
    if (activeTab === newTabId) {
        if (callback) callback();
        return;
    }

    console.log(`Switching tab from ${activeTab} to ${newTabId}`);
    const oldTab = activeTab;
    activeTab = newTabId;

    // Remove sketch if switching away from editor
    if (oldTab === 'editor' && userSketchInstance) {
        console.log("Removing sketch instance (tab switch).");
        try { userSketchInstance.remove(); } catch (e) { console.warn("Error removing p5 instance:", e); }
        userSketchInstance = null;
        previewContainer.html(''); // Ensure preview cleared
    }

    // Update content/visibility based on the NEW tab
    if (activeTab === 'info') {
        clearErrorSuccessDisplay(); // Clear potential errors
        displayInfo(); // Show formatted info text
    } else if (activeTab === 'settings') {
         clearInfoDisplay(); // Clear info text area
         clearErrorSuccessDisplay(); // Clear errors
         // Visibility handled by repositionElements
    } else { // Editor tab
        clearInfoDisplay(); // Clear info text area
        clearErrorSuccessDisplay(); // Clear errors
        // Attempt to restart sketch if needed
        if (!userSketchInstance) {
            console.log("Switched to Editor tab, updating sketch...");
            // Use short delay to ensure layout is ready
            setTimeout(() => updateSketch(editorContent || defaultSketch), 50);
        }
    }

    repositionElements(); // Update layout for the new tab configuration
    applyTheme(); // Ensure theme styles are correct for the new state

    if (callback) { // Execute callback after state change and UI updates
        setTimeout(callback, 0); // Use timeout to ensure it runs after current execution context
    }
}


