        .replace(/```([\s\S]*?)```/g, (match, p1) => `<pre><code>${p1.replace(/</g, '<').replace(/>/g, '>')}</code></pre>`)
        // Inline code
        .replace(/`([^`]+)`/g, '<code>$1</code>')
        // Headers
        .replace(/^## (.*$)/gim, '<h2 style="font-size: 1.4em; font-weight:'+FONT_WEIGHT_BOLD+'; margin-top: 1em; margin-bottom: 0.5em; border-bottom: 1px solid '+currentTheme.border+'; padding-bottom: 0.2em;">$1</h2>')
        .replace(/^### (.*$)/gim, '<h3 style="font-size: 1.2em; font-weight:'+FONT_WEIGHT_BOLD+'; margin-top: 0.8em; margin-bottom: 0.4em;">$1</h3>')
        // Bold
        .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
        // Horizontal rule
        .replace(/^---$/gm, '<hr style="border: none; border-top: 1px solid '+currentTheme.border+'; margin: 1.5em 0;">')
        // List items (basic)
        .replace(/^\* +(.*$)/gim, '<li style="margin-left: 20px; margin-bottom: 5px;">$1</li>')
         // Paragraphs (wrap lines not starting with special chars) - this is tricky, might over-wrap
        // .replace(/^([^<#\*\s].*)$/gim, '<p style="margin-bottom: 0.5em;">$1</p>')
        // Newlines to <br> (careful with lists/pre) - apply last
        .replace(/\n/g, '<br>');

     // Wrap list items in <ul> - Find first <li> and last </li>
     formattedHtml = formattedHtml.replace(/(\<li.*?\>)/, '<ul>$1'); // Add <ul> before first li
     formattedHtml = formattedHtml.replace(/(.*<\/li\>)(?![\s\S]*<\/li\>)/, '$1</ul>'); // Add </ul> after last li

    errorDisplay.html(formattedHtml);
