// ==================================================
// Code Execution & Management
// ==================================================

function updateCodeEditor(code) {
  editorContent = code;
  if (codeEditor) {
    codeEditor.value(code);
  }
  applyTheme(); // Ensure editor styles like font size are applied
}

function updateSketch(newCode) {
  // Ensure we only update if the editor tab is active
  if (activeTab !== 'editor') {
      console.warn("Update sketch attempt ignored: Not on Editor tab.");
      // Make sure preview is clear if update is blocked
      if (userSketchInstance) {
          try { userSketchInstance.remove(); } catch(e) {}
          userSketchInstance = null;
          previewContainer.html('');
      }
      return;
  }

  editorContent = newCode; // Store the latest code attempt
  var currentTheme = themes[darkMode ? 'dark' : 'light'];
  let success = false; // Track outcome

  // 1. Clear previous status messages and existing instance
  clearErrorSuccessDisplay(); // Clear the error/success area specifically
  clearInfoDisplay(); // Ensure info text isn't showing
  if (userSketchInstance) {
    try {
        userSketchInstance.remove();
        console.log("Previous sketch instance removed.");
    } catch (e) {
        console.warn("Could not remove previous sketch instance cleanly:", e);
    } finally {
        userSketchInstance = null;
        previewContainer.html(''); // Explicitly clear container's innerHTML
    }
  }

  // 2. Basic Syntax Check
  try {
    new Function('p', newCode); // Check if code is parseable JavaScript
    console.log("Syntax check passed.");
  } catch (error) {
    console.error("Syntax Error:", error);
    errorDisplay.html(`<strong style="color:${currentTheme.secondary};">Syntax Error:</strong><br><pre>${error.message}</pre><br>(Check code structure, braces, commas, etc.)`);
    errorDisplay.style('color', currentTheme.secondary); // Ensure color matches
    errorDisplay.style('border', `1px solid ${currentTheme.secondary}`);
    errorDisplay.style('background-color', currentTheme.editor);
    applyTheme(); // Re-apply to ensure consistency
    return; // Stop execution if syntax is bad
  }

  // 3. Prepare the sketch wrapper function for instance mode
  const sketchWrapper = (p) => {
      // --- Instance variable setup & Dimension helper ---
      const updateInstanceDimensions = () => {
          var previewRect = previewContainer.elt.getBoundingClientRect();
          p.width = previewRect.width > 0 ? previewRect.width : 100;
          p.height = previewRect.height > 0 ? previewRect.height : 100;
          p.windowWidth = p.width;
          p.windowHeight = p.height;
      };

      // --- Execute User Code and Define Core Functions ---
      try {
          // Execute the user's code string, passing the instance 'p'.
          // User code *must* define methods on 'p' (e.g., p.setup = function() {...}).
          new Function('p', newCode)(p);
          console.log("User code executed via new Function.");

          let warnings = [];
          // Check if p.setup was defined by the user code
          if (typeof p.setup !== 'function') {
              warnings.push("<code>p.setup = function() { ... }</code> not found. Added default.");
              p.setup = () => {
                  updateInstanceDimensions();
                  p.createCanvas(p.windowWidth, p.windowHeight);
                  p.background(50); p.fill(200); p.textAlign(p.CENTER); p.textSize(14);
                  p.text("Warning: p.setup not defined.", p.width / 2, p.height / 2 - 10);
              }
          }
          // Check if p.draw was defined by the user code
          if (typeof p.draw !== 'function') {
               warnings.push("<code>p.draw = function() { ... }</code> not found. Added default.");
               p.draw = () => {
                   // Avoid overwriting setup warning if both are missing
                   if (!warnings.some(w => w.includes("p.setup"))) {
                       p.background(100); p.fill(0); p.textAlign(p.CENTER); p.textSize(14);
                       p.text("Warning: p.draw not defined.", p.width / 2, p.height / 2);
                   }
               }
          }

          // Ensure a windowResized that uses the container dimensions correctly
          if (typeof p.windowResized === 'function') {
              // If user DID define one, wrap it to ensure dimensions are updated first
              const userResized = p.windowResized.bind(p); // Bind 'this' context correctly
              p.windowResized = () => {
                  updateInstanceDimensions(); // Update dimensions *before* calling user code
                  userResized(); // Call user's function
              };
          } else {
              // If user didn't define one, provide a default one
              p.windowResized = () => {
                   updateInstanceDimensions(); // Get fresh dimensions
                   p.resizeCanvas(p.windowWidth, p.windowHeight);
               };
          }

          // Display warnings if any were generated
           if (warnings.length > 0) {
              errorDisplay.html(`<strong style="color:${currentTheme.warning};">Warnings:</strong><br>- ${warnings.join('<br>- ')}`);
              errorDisplay.style('color', currentTheme.warning);
              errorDisplay.style('border', `1px solid ${currentTheme.warning}`);
              applyTheme(); // Ensure colors/bg match theme
           }

      } catch (runtimeError) {
          // Catch errors from *within* the user's code execution (e.g., calling undefined func)
          console.error("Runtime Error during initial user code execution:", runtimeError);
           errorDisplay.html(`<strong style="color:${currentTheme.secondary};">Runtime Error:</strong><br><pre>${runtimeError.message}</pre><br>(Check function calls, variables. See F12 Console for stack trace)`);
           errorDisplay.style('color', currentTheme.secondary);
           errorDisplay.style('border', `1px solid ${currentTheme.secondary}`);
           applyTheme();
          // Create a minimal canvas to show the error *in the preview area*
          p.setup = () => { updateInstanceDimensions(); p.createCanvas(p.windowWidth, p.windowHeight); };
          p.draw = () => {
              p.background(50); p.fill(currentTheme.secondary); p.textAlign(p.CENTER, p.CENTER);
              p.textFont('monospace'); p.textSize(12);
              p.text(`Runtime Error:\n${runtimeError.message}\n(Check F12 Console)`, p.width / 2, p.height / 2);
          };
          success = false; // Mark as failed, error shown in sketch
          // IMPORTANT: Rethrow the error so the outer catch block handles it and prevents p5 constructor call
          throw runtimeError;
      }
  };

  // 4. Create the new p5 instance inside the container
  try {
    previewContainer.style('display', 'block'); // Ensure container is visible

    // Critical step: Create the p5 instance, passing the wrapper function and container ID
    userSketchInstance = new p5(sketchWrapper, previewContainer.id());
    console.log("New p5 instance creation initiated.");

    // If we got here and no errors/warnings were logged to errorDisplay, it's a success
    if (!errorDisplay.elt.innerHTML.includes("Warning:") && !errorDisplay.elt.innerHTML.includes("Error:")) {
        success = true;
        errorDisplay.html(`<strong style="color:${currentTheme.tertiary};">Success:</strong> Sketch updated!`);
        errorDisplay.style('color', currentTheme.tertiary);
        errorDisplay.style('border', `1px solid ${currentTheme.tertiary}`);
        console.log("Sketch update marked as successful.");
        applyTheme();
    } else if (errorDisplay.elt.innerHTML.includes("Warning:")) {
        // If only warnings, still technically running
         success = true; // Sketch is running, albeit with warnings
         console.log("Sketch update completed with warnings.");
         // Styling already applied when warning was generated
    } else {
         // Errors were already displayed (Syntax or Runtime)
         console.log("Sketch update resulted in displaying an error message.");
         success = false;
    }

  } catch (p5ConstructorOrRuntimeError) {
    // Catch errors specifically from the p5 constructor OR runtime errors rethrown from sketchWrapper
    console.error("FATAL Error creating p5 instance or during runtime:", p5ConstructorOrRuntimeError);
     // Only update display if it doesn't already contain an Error message
     if (!errorDisplay.elt.innerHTML.includes("Error:")) {
         errorDisplay.html(`<strong style="color:${currentTheme.secondary};">Fatal Error:</strong><br><pre>${p5ConstructorOrRuntimeError.message}</pre><br>(Problem likely in p.setup/initial draw. Check F12 Console)`);
         errorDisplay.style('color', currentTheme.secondary);
         errorDisplay.style('border', `1px solid ${currentTheme.secondary}`);
         applyTheme();
     }
     if (userSketchInstance) { // Clean up if somehow instance was partially created
         try { userSketchInstance.remove(); } catch(e) {}
     }
     userSketchInstance = null;
     previewContainer.html(''); // Clear container
     success = false;
  }

  // Reposition elements AFTER the new instance might have created its canvas and adjusted container size
  setTimeout(repositionElements, 50); // Short delay helps ensure layout is stable
}


// ==================================================
// Theming
// ==================================================

function applyTheme() {
  if (!codeEditor) return; // Don't run if UI not ready
  var currentTheme = themes[darkMode ? 'dark' : 'light'];

  // Re-inject global styles to update CSS rules and base element styles
  injectGlobalStyles();

  // --- Direct Style Updates (for elements managed by p5.dom) ---

  // Editor, Error, Console base styles (mostly covered by CSS now)
  const codeAreas = [codeEditor, errorDisplay, consoleArea];
  codeAreas.forEach(el => {
      if (el) {
          el.style('background-color', currentTheme.editor);
          // Text color set by global body rule, can be overridden if needed
          // el.style('color', currentTheme.foreground);
          el.style('border', `1px solid ${currentTheme.border}`);
      }
  });

  // Specific font size for editor and console/error areas
  codeEditor.style('font-size', `${fontSize}px`);
  errorDisplay.style('font-size', `${fontSize * 0.95}px`); // Slightly smaller than editor
  consoleArea.style('font-size', `${fontSize * 0.9}px`); // Even smaller

  // Update Button Specific Styles (base from CSS, colors here)
  if (updateButton) {
    updateButton.style('background-color', currentTheme.accent);
    updateButton.style('color', currentTheme.editor);
    // Hover/active styles handled by injected CSS
  }

  // Error Display state-dependent styling (override base)
  if (errorDisplay && errorDisplay.elt.innerHTML) {
       if (errorDisplay.hasClass('info-display')) {
           displayInfo(); // Re-render info with current theme colors for code blocks etc.
           errorDisplay.style('border', `1px solid ${currentTheme.border}`); // Ensure correct border
           errorDisplay.style('color', currentTheme.foreground); // Ensure correct base color
       } else if (errorDisplay.elt.innerHTML.includes('Success')) {
           errorDisplay.style('color', currentTheme.tertiary);
           errorDisplay.style('border', `1px solid ${currentTheme.tertiary}`);
       } else if (errorDisplay.elt.innerHTML.includes('Warning')) {
           errorDisplay.style('color', currentTheme.warning);
           errorDisplay.style('border', `1px solid ${currentTheme.warning}`);
       } else if (errorDisplay.elt.innerHTML.includes('Error')) {
           errorDisplay.style('color', currentTheme.secondary);
           errorDisplay.style('border', `1px solid ${currentTheme.secondary}`);
       }
       // Ensure background always matches editor
       errorDisplay.style('background-color', currentTheme.editor);
  } else if (errorDisplay) {
       // Ensure empty error display has correct default style
       errorDisplay.style('color', currentTheme.foreground);
       errorDisplay.style('border', `1px solid ${currentTheme.border}`);
       errorDisplay.style('background-color', currentTheme.editor);
  }


  // Settings Panel Styling
  if (settingsPanel) {
    settingsPanel.style('background-color', currentTheme.panel);
    settingsPanel.style('color', currentTheme.foreground);
    settingsPanel.style('border', `1px solid ${currentTheme.border}`);

    // Update section title borders
    const titles = settingsPanel.elt.querySelectorAll('div[style*="font-size: 18px"]');
    titles.forEach(title => title.style.borderBottom = `1px solid ${currentTheme.border}`);

    // Update button styles within settings (colors)
    const settingButtons = settingsPanel.elt.querySelectorAll('button');
    settingButtons.forEach(btn => {
        btn.style.backgroundColor = currentTheme.accent;
        btn.style.color = currentTheme.editor;
    });
     // Update checkbox accent color (via global CSS injection)
const settingCheckboxes = settingsPanel.elt.querySelectorAll('input[type="checkbox"]');
settingCheckboxes.forEach(chk => {
  // accent-color via inline style
  chk.style.accentColor = currentTheme.accent;
  // Use the boolean property .checked, not a function
  chk.style.borderColor      = chk.checked ? currentTheme.accent : currentTheme.border;
  chk.style.backgroundColor  = chk.checked ? currentTheme.accent : currentTheme.editor;
});
     // Update span colors if needed (label text)
     const settingSpans = settingsPanel.elt.querySelectorAll('span');
     settingSpans.forEach(span => span.style.color = currentTheme.foreground);
  }

  updateConsoleDisplay(); // Update console message colors
}


// ==================================================
// Console Override & Display
// ==================================================

function overrideConsole() {
  const originalConsole = {
      log: console.log.bind(console), error: console.error.bind(console),
      warn: console.warn.bind(console), info: console.info.bind(console),
      clear: console.clear.bind(console),
  };

  // Robust argument formatting with circular reference handling
  const formatArgs = (args) => {
      const seen = new WeakSet();
      return Array.from(args).map(arg => {
          try {
              if (arg === null) return 'null';
              if (typeof arg === 'undefined') return 'undefined';
              if (typeof arg === 'string') return arg; // Return strings directly
              if (typeof arg === 'number' || typeof arg === 'boolean' || typeof arg === 'symbol') return String(arg);

              if (typeof arg === 'object') {
                  if (arg instanceof Error) {
                      return `Error: ${arg.message}${arg.stack ? `\nStack:\n${arg.stack}` : ''}`;
                  }
                  // Attempt to stringify objects, handle circular refs
                  return JSON.stringify(arg, (key, value) => {
                      if (typeof value === 'object' && value !== null) {
                          if (seen.has(value)) { return '[Circular Reference]'; }
                          seen.add(value);
                      }
                      return value;
                  }, 2); // Indent 2 spaces for readability
              }
              // Fallback for other types (like functions)
              return String(arg);
          } catch (e) {
              // Fallback if stringification or conversion fails
              try { return arg.toString(); } catch (tsErr) { return '[Unstringifiable Object]'; }
          }
      }).join(' '); // Join arguments with spaces
  };

  const addToConsole = (type, args) => {
      // Avoid logging if consoleArea isn't set up yet
      if (!consoleArea) {
          originalConsole[type] ? originalConsole[type](...args) : originalConsole.log(...args);
          return;
      }
      const message = formatArgs(args); // Ensure message is a string
      consoleOutput.push({ type: type, message: message, timestamp: new Date() });
      if (consoleOutput.length > 250) consoleOutput.shift();
      updateConsoleDisplay(); // Update the display immediately
  };

  console.log = function() { originalConsole.log.apply(console, arguments); addToConsole('log', arguments); };
  console.error = function() { originalConsole.error.apply(console, arguments); addToConsole('error', arguments); };
  console.warn = function() { originalConsole.warn.apply(console, arguments); addToConsole('warn', arguments); };
  console.info = function() { originalConsole.info.apply(console, arguments); addToConsole('info', arguments); };
  console.clear = function() {
      originalConsole.clear();
      consoleOutput = [];
      updateConsoleDisplay(); // Clear the display
  }
}

function updateConsoleDisplay() {
  if (!consoleArea) return;
  var currentTheme = themes[darkMode ? 'dark' : 'light'];
  let consoleHTMLContent = '';

  for (let item of consoleOutput) {
    let color = currentTheme.foreground;
    let prefix = '[LOG]';
    let fontWeight = 'normal';

    switch (item.type) {
      case 'error':
        color = currentTheme.secondary; prefix = '[ERR]'; fontWeight = 'bold'; break;
      case 'warn':
        color = currentTheme.warning; prefix = '[WRN]'; break;
      case 'info':
        color = currentTheme.accent; prefix = '[INF]'; break;
    }

    // **Defensive Check & Escaping**
    let messageToDisplay = '[Invalid Console Message]'; // Default fallback
    if (item && typeof item.message === 'string') {
        try {
            const escapedMessage = item.message
      .replace(/&/g,  '&amp;')
      .replace(/</g,  '&lt;')
      .replace(/>/g,  '&gt;')
      .replace(/"/g,  '&quot;')
      .replace(/'/g,  '&#39;');
            // Store the processed message
            messageToDisplay = escapedMessage.replace(/\n/g, '<br>'); // Handle newlines
        } catch (escapeError) {
             console.warn("Error escaping console message:", escapeError); // Log internal error
             messageToDisplay = '[Error Displaying Message]';
        }
    } else {
         originalConsole.warn("Invalid item found in consoleOutput:", item); // Use original console to avoid loops
    }

    // *** Use messageToDisplay which contains the processed/escaped string ***
    consoleHTMLContent +=
      `<div style="color: ${color}; margin-bottom: 4px; font-weight: ${fontWeight}; line-height: 1.4; font-family: '${FONT_NAME}', monospace;">
         <span style="opacity: 0.6; margin-right: 8px; user-select: none;">${prefix}</span>
         <span>${messageToDisplay}</span>
       </div>`;
  }

  consoleArea.html(consoleHTMLContent);
  // Ensure base color is set even if empty
  consoleArea.style('color', currentTheme.foreground);
  // Auto-scroll to bottom needs to happen *after* content is rendered
  setTimeout(() => {
      if (consoleArea && consoleArea.elt) {
         consoleArea.elt.scrollTop = consoleArea.elt.scrollHeight;
      }
  }, 0);
}


// ==================================================
// Event Handlers & Interactions
// ==================================================

function mousePressed() {
  // Check for resize handle press
  var handleX = width * (editorWidthPercent / 100);
  var resizerWidth = 10; // Interaction width
  var topBarHeight = 45;
  var statusBarHeight = 25;
  if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > handleX - resizerWidth && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < handleX + resizerWidth && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > topBarHeight && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < height - statusBarHeight) {
      isDragging = true;
      dragStartX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
      cursor('ew-resize');
      return; // Prevent other actions if resize starts
  }

  // Clicks inside previewContainer are handled by the user sketch instance automatically by p5.js
  // No specific code needed here for that.
}

function mouseReleased() {
  if (isDragging) {
    isDragging = false;
    cursor(ARROW);
    // Final reposition call might be useful if elements didn't perfectly track during drag
    repositionElements();
  }

  // Check for Tab clicks (moved from draw to handle click reliably)
  var topBarHeight = 45;
  var tabs = [ { name: 'Editor', id: 'editor' }, { name: 'Settings', id: 'settings' }, { name: 'Info', id: 'info' }];
  var tabWidth = 100;
  var tabSpacing = 5;
  var startX = width - (tabs.length * (tabWidth + tabSpacing)) - 15;

  for (let i = 0; i < tabs.length; i++) {
      var tab = tabs[i];
      var currentTabX = startX + i * (tabWidth + tabSpacing);
      // Check if mouse was released over a tab button area
      if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > currentTabX && (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) < currentTabX + tabWidth && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) > 0 && (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) < topBarHeight) {
           if (activeTab !== tab.id) { // Only trigger if not already active
               handleTabChange(tab.id);
               break; // Only handle one tab click per release
           }
      }
  }

  // User sketch mouseReleased is handled automatically by p5 instance if defined
}


function keyPressed() { // Global key presses (when editor textarea NOT focused)
  if (document.activeElement === codeEditor.elt) {
      return; // Let handleEditorKeyDown handle keys if editor is focused
  }

  // Global shortcuts (e.g., Fullscreen)
  if (keyCode === 122) { // F11
     toggleFullscreen();
     return false; // Prevent default F11 action
  }

  // Allow user sketch to handle keys if p5 instance exists and is running
  // p5.js automatically handles this check and calls user's keyPressed if defined
}

function toggleFullscreen() {
     if (!document.fullscreenElement) {
         document.documentElement.requestFullscreen().catch(err => {
             console.warn(`Fullscreen request failed: ${err.message}`);
             alert(`Fullscreen request failed: ${err.message}`); // Also notify user
         });
         isFullscreen = true;
     } else {
         if (document.exitFullscreen) {
             document.exitFullscreen();
             isFullscreen = false;
         }
     }
}

// Handles keys pressed ONLY when editor textarea has focus
function handleEditorKeyDown(e) {
    // Ctrl+S / Cmd+S for Update Code
    if ((e.ctrlKey || e.metaKey) && e.key === 's') {
        e.preventDefault();
        console.log("Ctrl/Cmd+S detected, updating sketch...");
        updateSketch(codeEditor.value());
        // Visual feedback: Flash the update button briefly
        if(updateButton) {
            var currentTheme = themes[darkMode ? 'dark' : 'light'];
            const originalColor = updateButton.style('background-color');
            const flashColor = currentTheme.tertiary; // Green flash
            updateButton.style('background-color', flashColor);
            updateButton.style('color', currentTheme.editor); // Ensure text contrast
            setTimeout(() => {
                if(updateButton) { // Check if button still exists
                    updateButton.style('background-color', currentTheme.accent); // Restore original accent
                 }
            }, 250);
        }
        return; // Stop processing this key event
    }

    // Tab Key Handling (Indent/Outdent)
    if (e.key === 'Tab' && autoIndent) {
        e.preventDefault(); // Prevent focus change
        const start = e.target.selectionStart;
        const end = e.target.selectionEnd;
        const value = e.target.value;
        const tabChar = '  '; // Use 2 spaces for indent

        // --- Multi-line selection indent/outdent ---
        const selection = value.substring(start, end);
        const includesNewline = selection.includes('\n');
        let lineStart = value.lastIndexOf('\n', start - 1) + 1;
        let effectiveEnd = (end > start && value[end - 1] === '\n') ? end - 1 : end;
        let lineEnd = value.indexOf('\n', effectiveEnd);
        if (lineEnd === -1) lineEnd = value.length;

        if (start !== end && includesNewline) { // Operate on full lines
             const affectedText = value.substring(lineStart, lineEnd);
             const lines = affectedText.split('\n');
             let processedText = '';
             let firstLinePrefixLength = 0;

             if (e.shiftKey) { // Outdent selected lines
                 processedText = lines.map((l, index) => {
                     if (l.startsWith(tabChar)) {
                          if (index === 0) firstLinePrefixLength = -tabChar.length;
                          return l.substring(tabChar.length);
                     } else if (l.startsWith(' ')) {
                          if (index === 0) firstLinePrefixLength = -1;
                          return l.substring(1);
                     }
                     if (index === 0) firstLinePrefixLength = 0;
                     return l;
                 }).join('\n');
             } else { // Indent selected lines
                 processedText = lines.map((l, index) => {
                      if (l.trim().length > 0 || l.length === 0) { // Indent non-blank lines and preserve blank lines
                        if (index === 0) firstLinePrefixLength = tabChar.length;
                        return tabChar + l;
                      } else {
                         if (index === 0) firstLinePrefixLength = 0;
                         return l;
                      }
                 }).join('\n');
             }
             e.target.value = value.substring(0, lineStart) + processedText + value.substring(lineEnd);
             e.target.selectionStart = max(lineStart, start + firstLinePrefixLength);
             e.target.selectionEnd = lineStart + processedText.length;

        } else { // --- Single line or no selection ---
             if (e.shiftKey) { // Outdent current line
                 let currentLineFull = value.substring(lineStart, lineEnd);
                 if (currentLineFull.startsWith(tabChar)) {
                     e.target.value = value.substring(0, lineStart) + currentLineFull.substring(tabChar.length) + value.substring(lineEnd);
                     e.target.selectionStart = max(lineStart, start - tabChar.length);
                     e.target.selectionEnd = max(lineStart, end - tabChar.length);
                 } else if (currentLineFull.startsWith(' ')) {
                     e.target.value = value.substring(0, lineStart) + currentLineFull.substring(1) + value.substring(lineEnd);
                     e.target.selectionStart = max(lineStart, start - 1);
                     e.target.selectionEnd = max(lineStart, end - 1);
                 }
             } else { // Indent (insert tab character)
                 e.target.value = value.substring(0, start) + tabChar + value.substring(end);
                 e.target.selectionStart = e.target.selectionEnd = start + tabChar.length;
             }
        }
        editorContent = e.target.value; // Update stored content
        codeEditor.elt.dispatchEvent(new Event('input')); // Trigger input event for frameworks etc.
        return; // Stop processing
    } // End Tab key

     // Comment Toggle (Ctrl + / or Cmd + /)
     if ((e.ctrlKey || e.metaKey) && e.key === '/') {
         e.preventDefault();
         var start = e.target.selectionStart;
         var end = e.target.selectionEnd;
         var value = e.target.value;
         var prefix = '// ';

         var lineStart = value.lastIndexOf('\n', start - 1) + 1;
         var effectiveEnd = (end > start && value[end - 1] === '\n') ? end - 1 : end;
         var lineEnd = value.indexOf('\n', effectiveEnd);
         if (lineEnd === -1) lineEnd = value.length;

         var affectedText = value.substring(lineStart, lineEnd);
         var lines = affectedText.split('\n');
         // Check non-empty lines *within the selection block*
         const nonEmptyLines = lines.filter(l => l.trim().length > 0);

         let allCommented = nonEmptyLines.length > 0 && nonEmptyLines.every(l => l.trim().startsWith('//'));
         let toggledText = '';
         let firstLineAdjustment = 0;

         if (allCommented) { // Uncomment
             toggledText = lines.map((l, index) => {
                 let trimmedStart = l.search(/\S|$/); // Find first non-whitespace char
                 if (l.substring(trimmedStart).startsWith(prefix)) {
                     let uncommentedLine = l.substring(0, trimmedStart) + l.substring(trimmedStart + prefix.length);
                     if (index === 0) firstLineAdjustment = -prefix.length;
                     return uncommentedLine;
                 } else {
                     if (index === 0) firstLineAdjustment = 0;
                     return l; // Keep line as is if not commented correctly
                 }
             }).join('\n');
         } else { // Comment
             toggledText = lines.map((l, index) => {
                 if (l.trim().length > 0) { // Only comment non-empty lines
                     if (index === 0) firstLineAdjustment = prefix.length;
                     return prefix + l;
                 } else {
                     if (index === 0) firstLineAdjustment = 0; // No change if first line is blank
                     return l; // Keep empty lines as they are
                 }
             }).join('\n');
         }

         e.target.value = value.substring(0, lineStart) + toggledText + value.substring(lineEnd);

         // Try to restore selection relative to the changes
         e.target.selectionStart = max(lineStart, start + firstLineAdjustment); // Adjust start based on first line's change
         e.target.selectionEnd = lineStart + toggledText.length; // Select the whole toggled block seems safest/simplest

         editorContent = e.target.value; // Update stored content
         codeEditor.elt.dispatchEvent(new Event('input'));
         return; // Stop processing
     } // End Comment toggle

} // End handleEditorKeyDown

